const messageContainer=document.getElementById("messageContainerID"),message=document.getElementById("messageID"),spiner=document.getElementById("spinerID"),messageFile=document.getElementById("messageFileID"),buttonSubmit=document.getElementById("buttonSubmitID"),inputFile=document.getElementById("inputFileID");document.getElementById("inputFileID").addEventListener("change",(event=>{const file=event.target.files[0];messageFile.innerHTML="<span style='color: black !important'>File: </span>"+file.name,file.name.endsWith(".bin")?(messageFile.style.color="green",buttonSubmit.disabled=!1):(messageFile.style.color="red",buttonSubmit.disabled=!0)})),document.getElementById("otaForm").addEventListener("submit",(event=>{event.preventDefault(),file=inputFile.files[0],file?file.name.endsWith(".bin")?(messageContainer.className="alert loading",message.textContent="OTA Update in Progress ... ",spiner.style.display="block",file.arrayBuffer().then((fileData=>{fetch("/ota_update",{method:"POST",headers:{"Content-Type":"application/octet-stream"},body:fileData}).then((response=>{response.text().then((data=>{response.ok?(messageContainer.className="alert success",message.textContent=data,spiner.style.display="none",setTimeout((()=>{window.location.href="./"}),1e3)):(console.error(`OTA Update failed: ${response.status} ${data}`),messageContainer.className="alert error",message.textContent=`OTA Update failed: ${response.status} ${data}`,spiner.style.display="none")}))})).catch((error=>{console.error("Error during OTA Update:",error),messageContainer.className="alert error",message.textContent="Error during OTA Update. See console for details.",spiner.style.display="none"}))}))):alert("Please select a .bin file!"):alert("Please select a firmware file!")}));